const ELEMENT_PROP_KEYS = new Set(["theme","highlight","align","hold","move","fontWeight","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  highlight: "ready to install.",
  align: "center",
  hold: 28,
  move: 28,
  fontWeight: 500,
  accent: "#3B5BFD",
  fontFamily: "Inter Tight",
  scale: 1,
  delay: 0,
  speed: 1,
};

type LayoutSwapElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LayoutSwapBase>;

const LayoutSwapInner = forwardRef<
  HTMLDivElement,
  LayoutSwapElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LayoutSwap>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LayoutSwapBase
          {...(componentProps as unknown as ComponentProps<typeof LayoutSwapBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LayoutSwap = Interactive.withSchema({
  Component: LayoutSwapInner,
  componentName: "<LayoutSwap>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
